/*
 * sampa_regs.h - Table of SAMPA register names.
 *
 * The implementation (sampa_regs.c) is GENERATED by gen_regs.py from the
 * GUI's CSV files:
 *
 *   resources/globreg.csv  -> global registers  (40)
 *   resources/chreg.csv    -> channel registers (31)
 *
 * Those CSV files are the source of truth: if the registers change, the .c
 * is regenerated and nothing is edited by hand.
 *
 *   make regs
 */
#ifndef SAMPA_REGS_H
#define SAMPA_REGS_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
  const char *name;       /* e.g. "VACFG"                         */
  uint8_t     addr;       /* address inside the SAMPA             */
  uint8_t     size;       /* useful width, in bits                */
  uint8_t     read_only;  /* 1 = read-only, cannot be set         */
  const char *desc;       /* plain-text description               */
} sampa_reg_t;

extern const sampa_reg_t sampa_glb_regs[];
extern const size_t      sampa_glb_regs_count;
extern const sampa_reg_t sampa_ch_regs[];
extern const size_t      sampa_ch_regs_count;

/* Look up by name, case-insensitive. NULL if it does not exist. */
const sampa_reg_t *sampa_find_glb(const char *name);
const sampa_reg_t *sampa_find_ch(const char *name);

#endif /* SAMPA_REGS_H */
